Here's how to handle each scenario with modern MSTest (3.9+/3.10+):

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PlatformAndEnvironmentTests
{
    private readonly TestContext _testContext;
    private string? _tempFile;

    public PlatformAndEnvironmentTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only (skipped on Linux/macOS)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Microsoft.Win32.Registry.GetValue(
            @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion",
            "ProductName", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void GpuRendering_ProducesExpectedOutput()
    {
        // Only runs locally, skipped in CI
        var result = GpuRenderer.Render(scene);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await _weatherClient.GetForecastAsync(
            _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Temp files — cleanup runs even on failure
    [TestMethod]
    public void Export_WritesValidFile()
    {
        // Arrange
        _tempFile = Path.GetTempFileName();

        // Act
        Exporter.WriteTo(_tempFile);

        // Assert
        Assert.IsTrue(File.Exists(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Key attributes:**

| Scenario | Attribute | Since |
|----------|-----------|-------|
| OS-specific | `[OSCondition(OperatingSystems.Windows)]` | MSTest 3.10 |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | MSTest 3.10 |
| Flaky/retry | `[Retry(3)]` | MSTest 3.9 |
| Cleanup on failure | `[TestCleanup]` method | All versions |

**Notes:**
- `[TestCleanup]` always runs after the test, regardless of pass/fail — ideal for temp file deletion.
- `[Retry]` should only be used for genuinely flaky external dependencies, not to mask race conditions.
- Combine `[Timeout]` with `TestContext.CancellationToken` for async tests to ensure clean cancellation.
